-- Proveedores de la organización 3 (Futura Farma - Mavisa), del archivo «ACT_PROVEEDORES.xls»
-- (1355 proveedores: 532 de la localidad 3-01 y 823 de la 3-02).
--   1. Si el proveedor ya existe en la localidad (mismo código o, si no, mismo NIT) NO se crea: se
--      actualiza.
--   2. Columnas nuevas de proveedores (vienen en el archivo y no estaban en la base de datos):
--      fax, origen (S/N), proveedor_principal, mostrar (S/N), cuenta_gasto_codigo y version
--      (CUENTA_CONTABLE y VERSION), regimen_isr_anterior (REGIMEN_ISR), descripcion_regimen,
--      acreditaciones, forma_pago_anterior (FORMA_PAGO), tipo_anterior (TIPO) y fecha_respaldo_anterior
--      (FECHA_BK).
--   Equivalencias: NOMBRE = nombre fiscal (o RAZON_SOCIAL si trae), NOMBRE_COMERCIAL y
--   NOMBRE_EMISION_DOCUMENTOS; DESCRIPCION_GENERAL = concepto de gastos (obligatorio: «POR DEFINIR»
--   si no trae); TIPO_PROVEEDOR = tipo de proveedor por su código (1 local = proveedor nacional);
--   CRITICO, EFECTUAR_RETENCION, PENDIENTE_REVISAR y VARIAS_CTAS S/N; ESTADO A/I; CORREOS = correo;
--   FORMA_PAGO C/R = CHEQUE/TRANSFERENCIA; BANCO, BODEGA y REGIMEN_ISR por su código (bancos y bodegas
--   de la localidad, scripts 82 y 87); la cuenta de gastos por su código en la versión del catálogo.
--   Lo que no se encuentra queda sin ligar con su código guardado y se informa.
--   Puede ejecutarse de nuevo: la segunda vez solo actualiza.
-- Se ejecuta después del script 87.

alter table public.proveedores add column if not exists fax text;
alter table public.proveedores add column if not exists origen text;
alter table public.proveedores add column if not exists proveedor_principal integer;
alter table public.proveedores add column if not exists mostrar boolean;
alter table public.proveedores add column if not exists cuenta_gasto_codigo text;
alter table public.proveedores add column if not exists version integer;
alter table public.proveedores add column if not exists regimen_isr_anterior integer;
alter table public.proveedores add column if not exists descripcion_regimen text;
alter table public.proveedores add column if not exists acreditaciones text;
alter table public.proveedores add column if not exists forma_pago_anterior text;
alter table public.proveedores add column if not exists tipo_anterior integer;
alter table public.proveedores add column if not exists fecha_respaldo_anterior timestamp;

-- Cada fila del archivo es un arreglo con las columnas en este orden (posición desde 0):
-- 0 LOCALIDAD, 1 PROVEEDOR, 2 NOMBRE, 3 NIT, 4 TELEFONOS, 5 CONTACTO, 6 DIRECCION, 7 EXTENSION,
-- 8 FAX, 9 DESCRIPCION_GENERAL, 10 TIPO_PROVEEDOR, 11 ORIGEN, 12 CRITICO, 13 RAZON_SOCIAL,
-- 14 ESTADO, 15 NOMBRE_COMERCIAL, 16 NOMBRE_EMISION_DOCUMENTOS, 17 PROVEEDOR_PRINCIPAL, 18 BANCO,
-- 19 CUENTA_BANCARIA, 20 EFECTUAR_RETENCION, 21 CORREOS, 22 REGIMEN_ISR, 23 FORMA_PAGO,
-- 24 DIAS_CREDITO, 25 MOSTRAR, 26 CUENTA_CONTABLE, 27 VERSION, 28 DESCRIPCION_REGIMEN,
-- 29 PENDIENTE_REVISAR, 30 BODEGA, 31 ACREDITACIONES, 32 VARIAS_CTAS, 33 TIPO, 34 FECHA_BK.

do $migra$
declare
  v_org bigint;
  v_loc bigint;
  v_id bigint;
  v_cuenta bigint;
  v_banco bigint;
  v_bodega bigint;
