  r jsonb;
  v_nuevos integer := 0;
  v_act integer := 0;
  v_sin_cuenta integer := 0;
  v_sin_regimen text := '';
  v_sin_bodega text := '';
  v_sin_banco text := '';
  v_omitidas text := '';
begin
