  [2,3243,"DO?A LUISA XICOTENCATL, S.A.","4976193",null,null,null,null,null,null,1,"S","N",null,"A","DOÑA LUISA XICOTENCATL","DO?A LUISA XICOTENCATL, S.A.",null,null,null,"N",null,3,null,0,"S",null,1,null,"S",null,null,"N",1,46330.410358796296],
  [2,3244,"GRUPO QUINSAGO GUATEMALA, SOCIEDAD ANÓNIMA","120531771",null,null,null,null,null,null,1,"S","N",null,"A","GRUPO QUINSAGO GUATEMALA","GRUPO QUINSAGO GUATEMALA, SOCIEDAD ANÓNIMA",null,null,null,"N",null,3,null,0,"S",null,1,null,"S",null,null,"N",1,46330.410358796296]
]$j$::jsonb) x
    order by (x->>0)::integer, (x->>1)::integer
  loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = (r->>0)::integer;
    if v_loc is null then
      if position(format('3-%s', lpad(r->>0, 2, '0')) in v_omitidas) = 0 then v_omitidas := v_omitidas || format(' 3-%s', lpad(r->>0, 2, '0')); end if;
      continue;
    end if;
    -- Proveedor existente: por código y, si no, por NIT (que no sea consumidor final).
    select id into v_id from public.proveedores where localidad_id = v_loc and codigo = (r->>1)::integer;
    if v_id is null and upper(replace(coalesce(r->>3, ''), ' ', '')) not in ('', 'CF', 'C/F') then
      select id into v_id from public.proveedores where localidad_id = v_loc and nit = upper(replace(r->>3, ' ', ''));
    end if;
    select k.id into v_cuenta from public.cuentas k join public.catalogos_cuentas g on g.id = k.catalogo_id
    where g.localidad_id = v_loc and k.codigo = r->>26
      and (g.version = (r->>27)::integer or (r->>27 is null and g.activo))
    order by g.version desc limit 1;
    if r->>26 is not null and v_cuenta is null then v_sin_cuenta := v_sin_cuenta + 1; end if;
    v_banco := (select b.id from public.bancos b where b.localidad_id = v_loc and b.codigo = (r->>18)::integer);
    if r->>18 is not null and v_banco is null and position(format(' %s;', r->>18) in v_sin_banco) = 0 then v_sin_banco := v_sin_banco || format(' %s;', r->>18); end if;
    v_bodega := (select b.id from public.bodegas b where b.localidad_id = v_loc and b.codigo = (r->>30)::integer);
    if r->>30 is not null and v_bodega is null then v_sin_bodega := v_sin_bodega || format(' 3-%s proveedor %s bodega %s;', lpad(r->>0, 2, '0'), r->>1, r->>30); end if;
    v_regimen := (select x.id from public.regimenes_isr x where x.codigo = (r->>22)::integer);
    if r->>22 is not null and v_regimen is null and position(format(' %s;', r->>22) in v_sin_regimen) = 0 then v_sin_regimen := v_sin_regimen || format(' %s;', r->>22); end if;

    if v_id is null then
      insert into public.proveedores (organizacion_id, localidad_id, codigo, nombre_comercial, concepto_gastos)
      values (v_org, v_loc, (r->>1)::integer, coalesce(r->>15, r->>2), coalesce(r->>9, 'POR DEFINIR'))
      returning id into v_id;
      v_nuevos := v_nuevos + 1;
    else
      v_act := v_act + 1;
    end if;
    update public.proveedores set
      nit = r->>3, nombre_comercial = coalesce(r->>15, r->>2),
      nombre_fiscal = coalesce(r->>13, r->>2), nombre_emision = r->>16,
      direccion = r->>6, concepto_gastos = coalesce(r->>9, 'POR DEFINIR'),
      telefonos = r->>4, extension = r->>7, contacto = r->>5, correo = r->>21,
      nacional = coalesce(r->>10, '1') = '1', servicio_critico = r->>12 = 'S',
      pendiente_revisar = r->>29 = 'S',
      tipo_proveedor_id = (select t.id from public.tipos_proveedor t where t.codigo = (r->>10)::integer),
      regimen_isr_id = v_regimen, bodega_id = v_bodega,
      estado = case when r->>14 = 'I' then 'INACTIVO' else 'ACTIVO' end,
      dias_credito = coalesce((r->>24)::integer, 0), efectuar_retencion = r->>20 = 'S',
      cuenta_gasto_id = v_cuenta, varias_cuentas = r->>32 = 'S',
      forma_pago = case when r->>23 = 'R' then 'TRANSFERENCIA' else 'CHEQUE' end,
      banco_id = v_banco, cuenta_bancaria = r->>19,
      fax = r->>8, origen = r->>11, proveedor_principal = (r->>17)::integer,
      mostrar = case r->>25 when 'S' then true when 'N' then false end,
      cuenta_gasto_codigo = r->>26, version = (r->>27)::integer,
      regimen_isr_anterior = (r->>22)::integer, descripcion_regimen = r->>28,
      acreditaciones = r->>31, forma_pago_anterior = r->>23, tipo_anterior = (r->>33)::integer,
      fecha_respaldo_anterior = case when r->>34 is not null then timestamp '1899-12-30' + ((r->>34)::numeric * interval '1 day') end
    where id = v_id;
  end loop;

  raise notice '%', format('Proveedores de la organización 3: %s nuevos, %s actualizados.%s%s%s%s%s',
    v_nuevos, v_act,
    case when v_sin_cuenta > 0 then format(' %s con una cuenta de gastos que no existe en el catálogo (queda su código).', v_sin_cuenta) else '' end,
    case when v_sin_regimen <> '' then ' Régimen ISR que no existe (queda su código):' || v_sin_regimen else '' end,
    case when v_sin_banco <> '' then ' Bancos que no existen en la localidad:' || v_sin_banco else '' end,
    case when v_sin_bodega <> '' then ' Bodegas que no existen:' || v_sin_bodega else '' end,
    case when v_omitidas <> '' then ' Localidades que no existen (omitidas):' || v_omitidas else '' end);
end;
$migra$;

notify pgrst, 'reload schema';
